def answer_couch_question(image):
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("people")
    if len(people_patches) < 2:
        return "There are fewer than two people in the image."

    people_patches.sort(key=lambda person: person.compute_depth(), reverse=True)
    closest_people = people_patches[:2]

    couch_patches = image_patch.find("couch")
    if not couch_patches:
        return "No couch found in the image."

    best_match = None
    min_distance = float('inf')

    for couch in couch_patches:
        for person in closest_people:
            dist = distance(couch, person)
            if dist < min_distance:
                min_distance = dist
                best_match = couch

    if best_match:
        return f"The couch where the two people are sitting is located at depth {best_match.compute_depth()}."
    else:
        return "The two people are not sitting on a couch."

