    image_patch = ImagePatch(image)
    boy_patches = image_patch.find("boy")
    clock_patches = image_patch.find("clock")

    if not boy_patches or not clock_patches:
        return image_patch

    boy_centers = [(p.left + p.right) / 2 for p in boy_patches]
    clock_centers = [(p.left + p.right) / 2 for p in clock_patches]

    boy_closest_clock = min(clock_centers, key=lambda x: abs(x - boy_centers[0]))

    return next((patch for patch in clock_patches if (patch.left + patch.right) / 2 == boy_closest_clock), clock_patches[0])

